#include <algorithm>
#include <cstdint>
#include <iostream>
#include <map>
#include <stdexcept>
#include <vector>
using namespace std;
void req(bool p,const char*s){if(!p)throw runtime_error(s);}
long long hp(const vector<int>&a){int n=a.size(),end=(1<<n)-1;vector<vector<long long>>dp(1<<n,vector<long long>(n));for(int v=0;v<n;v++)dp[1<<v][v]=1;for(int s=1;s<=end;s++)for(int v=0;v<n;v++)if(dp[s][v]){int choices=a[v]&~s;while(choices){int w=__builtin_ctz(choices);choices&=choices-1;dp[s|1<<w][w]+=dp[s][v];}}long long h=0;for(auto x:dp[end])h+=x;return h;}
int rank_subset(const vector<int>&a,int r){vector<int>O,I;for(int v=0;v<(int)a.size();v++)if(v!=r){if(a[r]>>v&1)O.push_back(v);else I.push_back(v);}vector<bool>s(1<<I.size());s[0]=true;for(int o:O){auto t=s;for(int m=0;m<(int)s.size();m++)if(s[m])for(int j=0;j<(int)I.size();j++)if(!(m>>j&1)&&(a[o]>>I[j]&1))t[m|1<<j]=true;s=t;}int ans=0;for(int m=0;m<(int)s.size();m++)if(s[m])ans=max(ans,__builtin_popcount((unsigned)m));return ans;}
// Independent labels: clones come first, then exterior vertices in old order.
vector<int> clone_first(const vector<int>&a,int r,int k){vector<int>old(k,r);for(int v=0;v<(int)a.size();v++)if(v!=r)old.push_back(v);int n=old.size();vector<int>b(n);for(int i=0;i<n;i++)for(int j=i+1;j<n;j++){bool ij=(i<k&&j<k)?true:(bool)(a[old[i]]>>old[j]&1);if(ij)b[i]|=1<<j;else b[j]|=1<<i;}return b;}

bool prime(long long x){if(x<2)return false;for(long long d=2;d*d<=x;d++)if(x%d==0)return false;return true;}
bool strong(const vector<int>&a){int n=a.size();for(int start=0;start<n;start++){int seen=1<<start;for(int it=0;it<n;it++){int next=seen;for(int v=0;v<n;v++)if(seen>>v&1)next|=a[v];seen=next;}if(seen!=(1<<n)-1)return false;}return true;}

long long iso(const vector<int>&a,const vector<int>&b,int rootA=-1,int rootB=-1){int n=a.size();vector<int>p(n,-1);vector<bool>used(n);long long count=0;auto rec=[&](auto&&self,int depth)->void{if(depth==n){count++;return;}int u=-1;vector<int>cand;for(int x=0;x<n;x++)if(p[x]<0){vector<int>c;for(int y=0;y<n;y++)if(!used[y]&&__builtin_popcount((unsigned)a[x])==__builtin_popcount((unsigned)b[y])&&(rootA<0||((x==rootA)==(y==rootB)))){bool ok=true;for(int z=0;z<n;z++)if(p[z]>=0&&(a[x]>>z&1)!=(b[y]>>p[z]&1))ok=false;if(ok)c.push_back(y);}if(u<0||c.size()<cand.size()){u=x;cand=c;}}for(int y:cand){p[u]=y;used[y]=true;self(self,depth+1);p[u]=-1;used[y]=false;}};rec(rec,0);return count;}
long long fixed_words(const vector<int>&a){int n=a.size();vector<int>w(n);for(int i=0;i<n;i++)w[i]=i;long long count=0;do{bool ok=true;for(int j=0;j<n-1;j++)if(!(a[w[j]]>>w[j+1]&1)){ok=false;break;}if(ok)for(int j=0;j<n;j++)if(w[j]!=n-1-w[n-1-j]){ok=false;break;}count+=ok;}while(next_permutation(w.begin(),w.end()));return count;}
int main(){map<int,vector<int>>expected={{1,{1}},{3,{1,1}},{5,{1,2,13}},{7,{2,6,154,350}},{9,{8,32,2544,10016,52936}}};long long total=0,rank2=0;map<long long,int>hits;for(int n:{1,3,5,7,9}){vector<pair<int,int>>reps;for(int i=0;i<n;i++)for(int j=i+2;j<n;j++)if(make_pair(i,j)<=make_pair(n-1-j,n-1-i))reps.push_back({i,j});req((int)reps.size()==(n-1)*(n-1)/4,"complete bit universe");vector<int>hist(n/2+1);map<long long,int>local;for(int mask=0;mask<(1<<(int)reps.size());mask++){vector<int>a(n);for(int i=0;i+1<n;i++)a[i]|=1<<(i+1);for(int k=0;k<(int)reps.size();k++){auto[i,j]=reps[k];int u=n-1-j,v=n-1-i;if(mask>>k&1){a[i]|=1<<j;a[u]|=1<<v;}else{a[j]|=1<<i;a[v]|=1<<u;}}for(int i=0;i<n;i++)for(int j=i+1;j<n;j++){req(((a[i]>>j&1)+(a[j]>>i&1))==1,"tournament");req((a[i]>>j&1)==(a[n-1-j]>>(n-1-i)&1),"anti");}total++;int q=rank_subset(a,n/2);hist[q]++;if(q!=2)continue;rank2++;long long h1=hp(a),h2=hp(clone_first(a,n/2,2));req(h2%4==1,"even clone residue");if(h2!=3*h1-2)continue;auto h3=hp(clone_first(a,n/2,3));if(h3!=9*h1-8)continue;req((h1-1)%3==0,"integral amplitude");long long A=(h1-1)/3;req(A%4==0,"amplitude residue");hits[A]++;local[A]++;if(A==72){vector<int>core={414,260,8,50,294,327,415,318,12};req(iso(a,core,n/2,4)==1,"unique rooted core in independent normalized bank");}}req(hist==expected[n],"rank histogram");cout<<"order "<<n<<" normalized "<<(1<<reps.size())<<" rank_histogram";for(int x:hist)cout<<" "<<x;cout<<" positive_clocks";for(auto[A,c]:local)cout<<" "<<A<<":"<<c;cout<<"\n";}req(total==66067&&rank2==2711,"complete totals");req(hits==map<long long,int>{{72,11},{200,19}},"complete positive amplitude bank");req(9765625LL>205LL*205*205,"all-order smaller amplitude cutoff");vector<int>a={414,260,8,50,294,327,415,318,12};int r=4;req(strong(a)&&hp(a)==217&&rank_subset(a,r)==2,"physical attaining source");req(iso(a,a)==1,"full automorphism rigidity");int clockroots=0;for(int v=0;v<9;v++)if(rank_subset(a,v)==2&&hp(clone_first(a,v,2))==649&&hp(clone_first(a,v,3))==1945){req(v==4,"root uniqueness");clockroots++;}req(clockroots==1,"one clock root");req(fixed_words(a)==11,"full-permutation fixed Hamilton words");cout<<"equality_normalized_presentations=11 rooted_core_classes=1 full_automorphisms=1 clock_roots=1 fixed_words=11\n";for(int i=0;i<9;i++)for(int j=i+1;j<9;j++)req((a[i]>>j&1)==(a[8-j]>>(8-i)&1),"source anti");long long h1=hp(a),h2=hp(clone_first(a,r,2)),h3=hp(clone_first(a,r,3));req((h1==217&&(h2-h1)/2==216&&(h3-h1-6*216)/6==72),"exact run vector");for(int m:{1,2,3,5,6,8}){auto b=clone_first(a,r,m);long long power=1;for(int j=0;j<m;j++)power*=3;long long H=hp(b);req(H==72*power+1&&strong(b),"all physical clone controls");vector<int>old;for(int v=0;v<9;v++)if(v!=r)old.push_back(v);vector<int>tau(b.size());for(int i=0;i<m;i++)tau[i]=m-1-i;for(int i=0;i<8;i++)for(int j=0;j<8;j++)if(old[j]==8-old[i])tau[m+i]=m+j;for(int i=0;i<(int)b.size();i++)for(int j=i+1;j<(int)b.size();j++)req((b[i]>>j&1)==(b[tau[j]]>>tau[i]&1),"clone anti");if(m==5||m==6||m==8)req(prime(H),"trial division prime certificate");cout<<"witness m="<<m<<" H="<<H<<" prime="<<prime(H)<<" rows";for(int x:b)cout<<" "<<x;cout<<" tau";for(int x:tau)cout<<" "<<x;cout<<"\n";}req(prime(31),"7p source quotient");for(int m=1;m<=200;m++){int r7=1;for(int j=0;j<m;j++)r7=r7*3%7;req(((2*r7+1)%7==0)==(m%6==1),"7-divisibility periodic control");}cout<<"PASS total="<<total<<" rank2="<<rank2<<" least_positive_unit_amplitude=72 only_7p_member=217\n";}
